   for(const feature of data.potential_areas||[]){
    if(potentialSurface(feature.properties).kind!=='potential')continue;
    const points=[];const visit=c=>{if(!Array.isArray(c))return;if(typeof c[0]==='number'&&typeof c[1]==='number')points.push(c);else c.forEach(visit);};visit(feature.geometry?.coordinates);if(!points.length)continue;
    const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);candidates.push({id:feature.properties.id,feature,lon:(Math.min(...xs)+Math.max(...xs))/2,lat:(Math.min(...ys)+Math.max(...ys))/2,kind:'factors'});
   }
