  const areas=snowObservations?.areas||[],summary=areas.map(a=>a.id.replace('_',' ')+' '+date(a.observed_from)+' ('+(observationState(a)==='RECENT'?'recente':'SCADUTA')+'); non osservabile '+fmt(100*a.unknown_pixels/a.pixels,1)+'%').join(' · ');
  period.textContent='Ultime acquisizioni satellitari: '+(summary||'nessuna disponibile')+'. Snapshot EO acquisito30/10; aggiornamento EO automatico non attivo. Freschezza massima24h: politica di aggiornamento, non soglia di sicurezza.';
  period.dataset.stale=String(!areas.some(a=>observationState(a)==='RECENT'));period.style.color='#f0c181';
  status.textContent=(quality?'Grigio evidenzia ciò che non possiamo verificare oggi. ':'Neve osservata su pendii: presenza della neve e predisposizione, instabilità non valutata. ')+'Copertura acquisita: GranSasso e Brenta; nelle altre aree montane italiane la neve osservata resta MANCANTE. '+(observationError?'Fonte osservata non disponibile: '+observationError+'.':'');
  temporalSummary.textContent='Potenziale pericolo combinato: NON ANCORA VALUTABILE. Manca la ricostruzione storica verificata degli strati e la valutazione della loro instabilità. Grigio e assenza di segnali non significano sicurezza.';
  sensorStatus.textContent='Copertura ottica osservata, non misura dell’altezza neve. Nivometri puntuali disponibili tramite Mostra nivometri; data e fuso verificati separatamente, non assimilati né estesi ai pendii.';
  supportNote.textContent='Instabilità, strati deboli, trasporto eolico locale e runout non verificati. Suolo e vegetazione restano contesto cartografico. Nessuna probabilità o grado ufficiale locale.';
